import java.util.*;
import java.io.*;

public class Main {
    static final int INF = 0x3f3f3f3f;
    static final long LINF = 0x3f3f3f3f3f3f3f3fL;
    static final int MAXN = 20;
    static final int MAXV = 2 * MAXN * MAXN;

    static char[][] m1 = new char[MAXN][MAXN];
    static char[][] m2 = new char[MAXN][MAXN];
    static int[][] inf_time = new int[MAXN][MAXN];
    static int n, t;

    static int[] dx = {1, 0, -1, 0};
    static int[] dy = {0, 1, 0, -1};

    static class Pair {
        int first, second;
        Pair(int a, int b) {
            first = a;
            second = b;
        }
    }

    static void bfs(int x, int y) {
        for (int a = 0; a < n; ++a)
            Arrays.fill(inf_time[a], INF);
        inf_time[x][y] = 0;
        Queue<Pair> fila = new LinkedList<>();
        fila.offer(new Pair(x, y));
        while (!fila.isEmpty()) {
            Pair front = fila.poll();
            int cx = front.first, cy = front.second;
            for (int a = 0; a < 4; ++a) {
                int nx = cx + dx[a], ny = cy + dy[a];
                if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
                if ('0' <= m1[nx][ny] && m1[nx][ny] <= '9' && inf_time[nx][ny] == INF) {
                    inf_time[nx][ny] = inf_time[cx][cy] + 1;
                    fila.offer(new Pair(nx, ny));
                }
            }
        }
    }

    static boolean[][] foi = new boolean[MAXN][MAXN];

    static List<Integer>[] adj = new ArrayList[MAXV];
    static int[][] cap = new int[MAXV][MAXV];

    static {
        for (int i = 0; i < MAXV; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static void insert_edge(int u, int v, int c) {
        adj[u].add(v);
        adj[v].add(u);
        cap[u][v] = c;
        cap[v][u] = 0;
    }

    static int[][] tempo = new int[MAXN][MAXN];
    static boolean[] dinic_foi = new boolean[MAXV];
    static int[] dist = new int[MAXV];

    static boolean dinic_bfs(int s, int t) {
        Arrays.fill(dist, -1);
        dist[s] = 0;
        Queue<Integer> fila = new LinkedList<>();
        fila.offer(s);
        while (!fila.isEmpty() && dist[t] == -1) {
            int v = fila.poll();
            for (int nxt : adj[v]) {
                if (cap[v][nxt] == 0 || dist[nxt] != -1) continue;
                dist[nxt] = dist[v] + 1;
                fila.offer(nxt);
            }
        }
        return dist[t] != -1;
    }

    static void bfs2(int px, int py) {
        for (int a = 0; a < n; ++a)
            Arrays.fill(tempo[a], INF);
        tempo[px][py] = 0;
        if ('1' <= m2[px][py] && m2[px][py] <= '9')
            insert_edge(n * px + py, n * n + n * px + py, INF);
        Queue<Pair> fila = new LinkedList<>();
        fila.offer(new Pair(px, py));
        while (!fila.isEmpty()) {
            Pair front = fila.poll();
            int x = front.first, y = front.second;
            for (int a = 0; a < 4; ++a) {
                int nx = x + dx[a], ny = y + dy[a];
                if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
                if (tempo[nx][ny] != INF) continue;
                if (!('0' <= m1[nx][ny] && m1[nx][ny] <= '9')) continue;
                if (tempo[x][y] + 1 <= Math.min(inf_time[nx][ny] - 1, t)) {
                    tempo[nx][ny] = tempo[x][y] + 1;
                    fila.offer(new Pair(nx, ny));
                }
                if (tempo[x][y] + 1 <= Math.min(inf_time[nx][ny], t) && ('1' <= m2[nx][ny] && m2[nx][ny] <= '9'))
                    insert_edge(n * px + py, n * n + n * nx + ny, INF);
            }
        }
    }

    static int dinic(int s, int t) {
        int ret = 0, got;
        while (dinic_bfs(s, t)) {
            Arrays.fill(dinic_foi, false);
            while ((got = dinic_dfs(s, t, INF)) != 0) {
                ret += got;
            }
        }
        return ret;
    }

    static int dinic_dfs(int v, int t, int flow) {
        if (v == t) return flow;
        dinic_foi[v] = true;
        for (int nxt : adj[v]) {
            if (cap[v][nxt] == 0 || dinic_foi[nxt] || dist[nxt] != dist[v] + 1) continue;
            int got = dinic_dfs(nxt, t, Math.min(flow, cap[v][nxt]));
            if (got != 0) {
                cap[v][nxt] -= got;
                cap[nxt][v] += got;
                return got;
            }
        }
        return 0;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        int s = MAXV - 2;
        int t_node = MAXV - 1;

        int ix = -1, iy = -1;

        for (int a = 0; a < n; ++a) {
            String line = br.readLine();
            for (int b = 0; b < n; ++b) {
                m1[a][b] = line.charAt(b);
                if (m1[a][b] == 'Z') {
                    ix = a;
                    iy = b;
                } else if ('1' <= m1[a][b] && m1[a][b] <= '9') {
                    insert_edge(s, a * n + b, m1[a][b] - '0');
                }
            }
        }

        bfs(ix, iy);

        for (int a = 0; a < n; ++a) {
            String line = br.readLine();
            for (int b = 0; b < n; ++b) {
                m2[a][b] = line.charAt(b);
                if ('1' <= m2[a][b] && m2[a][b] <= '9') {
                    insert_edge(n * n + a * n + b, t_node, m2[a][b] - '0');
                }
            }
        }

        for (int a = 0; a < n; ++a) {
            for (int b = 0; b < n; ++b) {
                if ('1' <= m1[a][b] && m1[a][b] <= '9') {
                    bfs2(a, b);
                }
            }
        }

        System.out.println(dinic(s, t_node));
    }
